import unittest

from textkit import cli


class CliTest(unittest.TestCase):
    def test_count(self):
        with tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False) as handle:
            handle.write("a b c")
        self.assertEqual(cli.count_words(handle.name), 3)


if __name__ == "__main__":
    unittest.main()

